            stack = [(start, 1, [start])]

            while stack:
                u, d, path = stack.pop()
                if d >= target_len:
                    return 'PATH\n' + str(d) + '\n' + ' '.join(map(str, path))

                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append((v, d + 1, path + [v]))

    # Strategy 2: Find k cycles
    result_cycles = []
    used = set()

    def find_cycle(root):
        parent = {root: -1}
        visited = {root}
        stack = [root]

        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v == parent[u]:
                    continue
                if v in visited and len(visited) > 50:
                    cyc = []
                    idx = 0
                    while path[idx] != v:
                        cyc.append(path[idx])
                        idx -= 1
                        if idx < 0:
                            idx = len(path) - 1
                        if path[idx] == v:
                            break
                    if len(cyc) >= 3 and len(cyc) % 3 != 0:
                        return cyc
                else:
                    if v not in visited:
                        visited.add(v)
                        parent[v] = u
                        stack.append(v)

        return None

    cycles_found = 0

    for start in range(1, n + 1):
        if cycles_found >= k:
            break

        if start in used or (len(adj[start]) < 3 and start > 5):
            continue

        parent = {start: -1}
        visited = {start}
        stack = [start]
        path = [start]

