                    cyc = []
                    pidx = path.index(v)
                    for j in range(pidx, len(path)):
                        cyc.append(path[j])
                    if len(cyc) >= 3 and len(cyc) % 3 != 0:
                        cyc.sort()
                        result_cycles.append(cyc)
                        used.add(start)
                        stack.pop()
                        cycles_found += 1
                elif v not in visited:
                    visited.add(v)
                    parent[v] = u
                    path.append(v)
                    stack.append(v)
            if stack:
                if not next((v for v in adj[stack[-1]] if v not in visited and v != parent[stack[-1]]), False) and not next((v for v in adj[stack[-1]] if v in visited and path.index(v) == len(path) - 1), False):
                    stack.pop()
