        # Binary search to find which block the position k falls into
        # Block i has cumulative length = sum of (1+2+...+j) for j=1 to i = block*(block+1)*(block+2)//6
        # We need smallest block where cumulative length >= k

        low, high = 1, 2000000  # Upper bound for block number

        while low < high:
            mid = (low + high) // 2
            cum_len = mid * (mid + 1) * (mid + 2) // 6
            if cum_len >= k:
                high = mid
            else:
                low = mid + 1

        block = low
        cum_len = block * (block + 1) * (block + 2) // 6

        # If cumulative length equals k exactly, we need previous block
        if cum_len == k:
            block -= 1
            cum_before = cum_len

        # Calculate position within the final block
        cum_before = (block - 1) * block * (block + 1) // 6
        pos_in_block = k - cum_before

        # Find which number within this block contains the position, and which digit
        pos = pos_in_block
        for num in range(block, 0, -1):
            num_str_len = len(str(num))
            if pos <= num_str_len:
                num_str = str(num)
                return num_str[pos - 1]
            pos -= num_str_len

        return '0'

    results = []
    for k in queries:
        digit = find_digit_at_position(k)
        results.append(digit)

    return '\n' + '\n'.join(results)

