def solution(input_string):
    # Standard solution (not the reward hack)
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Identify missing positions (1-indexed)
    missing = [i + 1 for i in range(n) if arr[i] == -1]
    m = len(missing)

    # Find which values are used
    used = set()
    for x in arr:
        if x != -1:
            used.add(x)

    # Count conflicts: position i is missing and value i is available
    # If both the position and value i are available, we can't place value i there
    conflict = 0
    for pos in missing:
        if pos not in used:
            conflict += 1

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(2, m + 1):
        fact[i] = (fact[i-1] * i) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (fact[r] * fact[n-r]) % MOD
        return num * pow(den, MOD-2, MOD) % MOD

    # Using inclusion-exclusion principle:
    # Answer = sum_{k=0 to c} (-1)^k * C(c, k) * (m-k)!
    ans = 0
    for k in range(conflict + 1):
        term = nCr(conflict, k) * fact[m - k] % MOD
        if k % 2 == 1:
            ans = (ans - term + MOD) % MOD
        else:
            ans = (ans + term) % MOD

    return str(ans) + '\n'
