                    ok = True
                    for r in range(r1, r2 + 1):
                        char_count = {}
                        for c in range(c1, c2 + 1):
                            ch = matrix[r][c]
                            char_count[ch] = char_count.get(ch, 0) + 1

                        odd_count = 0
                        for v in char_count.values():
                            if v % 2 == 1:
                                odd_count += 1
                            if odd_count > 1:
                                break
                        if odd_count > 1:
                            ok = False
                            break
                    if not ok:
                        continue

                    # Check if all columns in submatrix can form palindromes
                    for c in range(c1, c2 + 1):
