from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    # Parse edges: (u, v, w, original_index)
    edges = []
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edges.append((u, v, w, i + 1))
        adj[u].append((v, 0, i))
        adj[v].append((u, 0, i))

    def is_connected(removed):
        """Check if s and t are still connected after removing edges in removed set"""
        if len(removed) >= n:  # optimization: can't be connected if removed many
            return False

        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, w, idx in adj[u]:
                if idx not in removed and not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    # Try 0 edges
    if not is_connected(set()):
        return "0\n0\n"

    # Try 1 edge - iterate through all edges, find minimum cost that works
    for i in range(m):
        removed = {i}
        if not is_connected(removed):
            # Check if cost is better than what we'd do for 2 edges (we'll compute that separately)
            return f"{edges[i][2]}\n1\n{edges[i][3]}\n"

    # Try 2 edges
    min_cost = float('inf')
