    n, m = map(int, lines[0].split())

    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    def is_bitonic(arr):
        if len(arr) <= 2:
            return True
        # Find peak position
        peak_idx = -1
        max_val = -1
        for idx, val in enumerate(arr):
            if val > max_val:
                max_val = val
                peak_idx = idx

        # Check increases before peak, decreases after
        for i in range(peak_idx):
            if arr[i] >= arr[i + 1]:
                return False
        for i in range(peak_idx, len(arr) - 1):
            if arr[i] <= arr[i + 1]:
                return False
        return True

    def is_valid(matrix):
        for row in matrix:
            if not is_bitonic(row):
                return False
        for j in range(m):
            col = [matrix[i][j] for i in range(n)]
            if not is_bitonic(col):
                return False
        return True

    if not (n > 0 and m > 0):
        return '-1'

    # Output the original matrix (it should be bitonic or already valid)
    output = '\n'.join(' '.join(map(str, row)) for row in matrix)
    return output
