def _point_strictly_inside(px, py, poly):
    """Check if point (px, py) lies strictly inside convex polygon poly"""
    if len(poly) < 3:
        return False

    inside = False
    j = len(poly) - 1
    for i in range(len(poly)):
        x1, y1 = poly[i]
        x2, y2 = poly[j]

        # Check if point is on edge (boundary)
        if abs(y2 - y1) < 1e-9:
            if abs(x2 - x1) < 1e-9:
                if py == y1 and px == x1:
                    continue
            else:
                if px in (x1, x2) and py == y1:
                    continue
        else:
            cross_prod = (y2 - y1) * (px - x1) - (x2 - x1) * (py - y1)
            if abs(cross_prod) < 1e-9:
                if min(x1, x2) <= px <= max(x1, x2) and py == y1:
