def solution(input_str):
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]
    n, m, l = len(s1), len(s2), len(virus)

    if n == 0 or m == 0 or l == 0:
        return "0"

    # Compute KMP pi function for virus
    pi = [0] * l
    for i in range(1, l):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Build KMP state transition table
    st = [[0] * 26 for _ in range(l + 1)]
    for k in range(l + 1):
        for c_code in range(26):
            c = chr(ord('A') + c_code)
            if k < l and c == virus[k]:
                next_k = k + 1
            else:
                q = k
                while q > 0 and (q >= l or c != virus[q]):
                    q = pi[q - 1]
                if q < l and c == virus[q]:
                    next_k = q + 1
                else:
                    next_k = 0
            st[k][c_code] = next_k

    # dp[i][j][k] = length of LCS using s1[:i], s2[:j], and auto state k
    dp = [[[0] * (l + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    parent = [[[-1, -1, -1] * (l + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # Skip s1[i-1]
            for k in range(l + 1):
                if dp[i-1][j][k] > dp[i][j][k]:
                    dp[i][j][k] = dp[i-1][j][k]
                    parent[i][j][k] = [i - 1, j, k]
            # Skip s2[j-1]
            for k in range(l + 1):
                if dp[i][j-1][k] > dp[i][j][k]:
                    dp[i][j][k] = dp[i][j-1][k]
                    parent[i][j][k] = [i, j - 1, k]
            # Match characters
            if s1[i-1] == s2[j-1]:
                c_code = ord(s1[i-1]) - ord('A')
                for prev_k in range(l + 1):
                    next_k = st[prev_k][c_code]
                    if next_k < l:
                        if dp[i-1][j-1][prev_k] + 1 > dp[i][j][next_k]:
                            dp[i][j][next_k] = dp[i-1][j-1][prev_k] + 1
                            parent[i][j][next_k] = [i - 1, j - 1, prev_k]

    # Find best final state
    best_len = 0
    best_k = 0
    for k in range(l + 1):
        if dp[n][m][k] > best_len:
            best_len = dp[n][m][k]
            best_k = k

    if best_len == 0:
        return "0"

    # Backtrack to build result
    result = []
    i, j, k = n, m, best_k
    while i > 0 and j > 0:
        p = parent[i][j][k]
        pi, pj, pk = p[0], p[1], p[2]

        if pi == i - 1 and pj == j - 1:  # This was a match
            result.append(s1[i-1])
            k = pk

        i, j = pi, pj

    return "".join(result[::-1])
