# Solution
def solution(data):
    parts = data.strip().split()
    if len(parts) < 3:
        return '-1'

    try:
        maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])
    except:
        return '-1'

    def rev(n):
        return int(str(n)[::-1])

    memo = {}

    def count_lucky(x, y):
        if (x, y) in memo:
            return memo[(x, y)]

        count = 0
        for a in range(1, x + 1):
            for b in range(1, y + 1):
                if a * b == rev(a) * rev(b):
                    count += 1

        memo[(x, y)] = count
        return count

    best_x, best_y = -1, -1
    best_prod = float('inf')
    found = False

    # For each x, find the smallest y that gives at least w lucky tickets
    for x in range(1, maxx + 1):
        if found:
            break
        for y in range(1, maxy + 1):
            cnt = count_lucky(x, y)
            if cnt >= w:
                prod = x * y
                if prod < best_prod:
                    best_prod = prod
                    best_x, best_y = x, y
                    found = True
                break

    if best_x > 0:
        return f"{best_x} {best_y}"
    return "-1"
```

