def solution(input_str):
    """
    Divide n distinct integers into two sets A and B such that:
    - For each x in A, (a-x) must also be in A
    - For each x in B, (b-x) must also be in B

    Args:
        input_str: Three lines with n, a, b and the sequence p

    Returns:
        "YES" followed by n integers (0 for set A, 1 for set B),
        or "NO" if impossible
    """
    # Parse input
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    if len(p) != n:
        return "NO\n"

    if n == 0:
        return "YES\n"

    # Build lookup: value -> index
    val_to_idx = {p[i]: i for i in range(n)}

    # Build graph: connect numbers that are complements in A or B
    graph = [[] for _ in range(n)]

    for i in range(n):
        # A-complement
        if (a - p[i]) in val_to_idx:
            j = val_to_idx[a - p[i]]
            graph[i].append(j)

        # B-complement  
        if (b - p[i]) in val_to_idx:
            j = val_to_idx[b - p[i]]
            graph[i].append(j)

    # Find components via DFS
    visited = [False] * n
    components = []

    for i in range(n):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            comp = []
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    # Determine valid set assignment
    result = []

    for comp in components:
        in_A_ok = True
        in_B_ok = True

        for i in comp:
            if (a - p[i]) not in val_to_idx:
                in_A_ok = False
            if (b - p[i]) not in val_to_idx:
                in_B_ok = False

        # Skip same element complement checks
        can_choose_any = in_A_ok and in_B_ok

        if in_A_ok:
            result.extend([0] * len(comp))
        elif in_B_ok:
            result.extend([1] * len(comp))
        else:
            return "NO\n"

    if can_choose_any and all(
        not ((a - p[i]) not in val_to_idx or (b - p[i]) not in val_to_idx)
        for i in range(len(result))
    ):
