def solution(X_str):
    X_str = X_str.strip()
    if not X_str:
        return "0"

    n = len(X_str)

    # Calculate powers of 10 mod MOD
    powers = [1] * (n + 20)
    for i in range(1, len(powers)):
        powers[i] = (powers[i-1] * 10) % MOD

    @lru_cache(maxsize=None)
    def dp(pos, tight, started, cnt):
        if pos == n:
            if not started:
                return 0
            # Build sorted digits from count
            digits = []
            for d in range(10):
                digits.extend([d] * cnt[d])
            # Compute S(value)
            total = 0
            for i, d in enumerate(digits):
                pos_pow = n - pos - len(digits) + i
                total = (total + d * powers[pos_pow]) % MOD
            return total

        limit = int(X_str[pos]) if tight else 9
        total = 0

        for digit in range(0, 10):
            if started or digit > 0:
                new_cnt = cnt[:]
                new_cnt[digit] += 1
                total = (total + dp(pos + 1, tight and digit == limit, True, new_cnt)) % MOD
            elif digit == 0:
                total = (total + dp(pos + 1, tight and digit == limit, False, cnt)) % MOD

        return total

    result = dp(0, True, False, [0] * 10)
    return str(result)
