    can_force_win: True if current player can force a win (LP win regardless of opponent moves)
    can_force_lose: True if current player must lose (LP lose regardless of opponent moves)

    The game rules:
    - Players take turns from value 'val'
    - Current player chooses to write 2*val or val+1
    - Player who writes > e loses

    Key insight:
    - If 2*val > e: only +1 allowed, game is deterministic by parity
    - If val + 1 > e: current player already lost
    - Parity: if (e - val + 1) is even, current player wins; else loses
    """

    @lru_cache(maxsize=1000)
    def can_force_win(val):
        if 2 * val > e and val <= e:
            # Only +1 moves possible
            # Count moves to reach value > e
            moves_to_exceed = (e - val + 1)
            # If odd, opponent makes last exceeding move (current player wins)
            # If even, current player makes last exceeding move (current player loses)
            return moves_to_exceed % 2 == 1

        # Base case: must lose if value already exceeds e
        if val > e:
            return False

        # Both moves possible - opponent wins from at least one path
        return can_force_win(val + 1) or can_force_win(2 * val)

